import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';

import 'package:nothingness/models/audio_track.dart';

import '../dev/main_test.dart' as app;
import '../dev/test_harness.dart';
import '../dev/test_overlay.dart';

Future<void> _pumpUntil(
  WidgetTester tester,
  bool Function() condition, {
  Duration timeout = const Duration(seconds: 3),
  Duration step = const Duration(milliseconds: 50),
}) async {
  final deadline = DateTime.now().add(timeout);
  while (DateTime.now().isBefore(deadline)) {
    await tester.pump(step);
    if (condition()) return;
  }
  throw TestFailure('Condition not met within ${timeout.inMilliseconds}ms');
}

void _loadTenTracks(List<AudioTrack> tracks) {
  // Helper to build 10 tracks from manifest-like names if needed.
  // This project ships 10 fixture opus files under evals/assets/opus/.
  // We rely on a test manifest in the fixture directory, but the test harness
  // uses a deterministic fake transport; the exact file contents are not needed.
  // This function is a placeholder to illustrate how to push tracks if not using a manifest.
}

// A smoke test that populates the queue with the 10 fixture opus files in the
// repository and exercises Play/Pause, Next (Skip) and Seek (Fast-forward) via
// the test overlay UI and PlaybackController API.
void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  group('media smoke test: play/pause, skip, seek', () {
    late final List<AudioTrack> tenTracks;

    setUp(() {
      TestHarness.instance.reset();
    });

    testWidgets('play/pause, skip (next), and fast-forward', (tester) async {
      // Start the test app
      await app.main();
      await tester.pumpAndSettle();

      final h = TestHarness.instance;

      // Build ten tracks corresponding to the 10 fixture opus files in media.
      tenTracks = [
        const AudioTrack(path: 'evals/assets/opus/01-undercover-49.opus', title: 'Unknown Artist - Unknown Title', artist: '49'),
        const AudioTrack(path: 'evals/assets/opus/02-undercover-50.opus', title: 'Unknown Artist - Unknown Title', artist: '50'),
        const AudioTrack(path: 'evals/assets/opus/03-undercover-51.opus', title: 'Unknown Artist - Unknown Title', artist: '51'),
        const AudioTrack(path: 'evals/assets/opus/04-undercover-52.opus', title: 'Unknown Artist - Unknown Title', artist: '52'),
        const AudioTrack(path: 'evals/assets/opus/05-undercover-53.opus', title: 'Unknown Artist - Unknown Title', artist: '53'),
        const AudioTrack(path: 'evals/assets/opus/06-undercover-54.opus', title: 'Unknown Artist - Unknown Title', artist: '54'),
        const AudioTrack(path: 'evals/assets/opus/07-undercover-44.opus', title: 'Unknown Artist - Unknown Title', artist: '44'),
        const AudioTrack(path: 'evals/assets/opus/08-undercover-45.opus', title: 'Unknown Artist - Unknown Title', artist: '45'),
        const AudioTrack(path: 'evals/assets/opus/09-undercover-46.opus', title: 'Unknown Artist - Unknown Title', artist: '46'),
        const AudioTrack(path: 'evals/assets/opus/10-undercover-47.opus', title: 'Unknown Artist - Unknown Title', artist: '47'),
      ];

      await h.setQueue(tenTracks);
      await tester.pumpAndSettle();

      // Start playback via UI play button
      await tester.tap(find.byKey(TestKeys.playPause));
      await tester.pumpAndSettle();

      // Wait until playing is true
      await _pumpUntil(tester, () {
        return find.textContaining('playing=true').evaluate().isNotEmpty;
      });

      // Skip to next track (Next button)
      await tester.tap(find.byKey(TestKeys.next));
      await tester.pumpAndSettle();

      // Verify queue index advanced to 1
      await _pumpUntil(tester, () {
        return find.textContaining('idx=1').evaluate().isNotEmpty;
      });

      // Fast-forward by seeking to 20 seconds
      await h.controller?.seek(const Duration(seconds: 20));
      await tester.pumpAndSettle();
      // Read the playback position from the transport to verify seek occurred
      final pos = await h.transport.position;
      expect(pos, Duration(seconds: 20));

      // Optionally, issue another seek forward to 40 seconds
      await h.seek(Duration(seconds: 40));
      await tester.pumpAndSettle();
      final pos40 = await h.transport.position;
      expect(pos40, Duration(seconds: 40));
    });
  });
}

